    --accent-color: #007aff;
    --accent-bg-color: #007aff;
    --accent-fg-color: #ffffff;
    --window-bg-color: #f2f2f7;
    --window-fg-color: #1c1c1e;
    --view-bg-color: #ffffff;
    --view-fg-color: #1c1c1e;
    --headerbar-bg-color: #f5f5f7;
    --headerbar-fg-color: #1c1c1e;
    --headerbar-backdrop-color: #f2f2f7;
    --sidebar-bg-color: #ebebf0;
    --sidebar-fg-color: #1c1c1e;
    --sidebar-backdrop-color: #f2f2f7;
    --sidebar-border-color: rgba(0, 0, 0, 0.12);
    --card-bg-color: #ffffff;
    --card-fg-color: #1c1c1e;
    --popover-bg-color: #ffffff;
    --popover-fg-color: #1c1c1e;
    --dialog-bg-color: #f5f5f7;
    --dialog-fg-color: #1c1c1e;
    --destructive-bg-color: #ffdad6;
    --destructive-fg-color: #93000a;
    --error-bg-color: #ffdad6;
    --error-fg-color: #93000a;
    --warning-bg-color: #fff4d6;
    --warning-fg-color: #614700;
    --success-bg-color: #d9f2e3;
    --success-fg-color: #0b3d24;
    --shade-color: rgba(0, 0, 0, 0.12);
}

@media (prefers-color-scheme: dark) {
    :root {
        --accent-color: #64aaff;
