        --dialog-bg-color: #242426;
        --dialog-fg-color: #f5f5f7;
        --destructive-bg-color: #3a0000;
        --destructive-fg-color: #ffffff;
        --error-bg-color: #3a0000;
        --error-fg-color: #ffffff;
        --warning-bg-color: #2a220f;
